import{_ as t,o as e,c as r,a2 as i}from"./chunks/framework.CDA9RsCr.js";const u=JSON.parse('{"title":"快速开始","description":"","frontmatter":{},"headers":[],"relativePath":"intro/quickstart.md","filePath":"intro/quickstart.md","lastUpdated":1794581028000}'),l={name:"intro/quickstart.md"};function o(d,a,c,n,s,h){return e(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h1><h2 id="_1-下载" tabindex="-1">1. 下载 <a class="header-anchor" href="#_1-下载" aria-label="Permalink to &quot;1. 下载&quot;">​</a></h2><p>前往 <a href="https://github.com/aDarkMaker/BiliLuckyDraw/releases" target="_blank" rel="noreferrer">Releases</a> 下载对应系统的安装包：</p><table tabindex="0"><thead><tr><th>平台</th><th>文件</th></tr></thead><tbody><tr><td>macOS（Apple Silicon / Intel）</td><td><code>BiliLuckyDraw-darwin-universal.zip</code></td></tr><tr><td>Windows</td><td><code>luckydraw-amd64-installer.exe</code>（安装版）或 <code>luckydraw.exe</code>（绿色版）</td></tr></tbody></table><p>macOS 首次打开若被系统拦截，在「系统设置 → 隐私与安全性」里选择仍要打开即可。</p><h2 id="_2-登录" tabindex="-1">2. 登录 <a class="header-anchor" href="#_2-登录" aria-label="Permalink to &quot;2. 登录&quot;">​</a></h2><p>启动后选择一种方式登录 B 站账号：</p><ul><li><strong>凭证登录</strong>：从浏览器复制 B 站 Cookie，粘贴到输入框后点击登录。</li><li><strong>扫码登录</strong>：切换到「扫码登录」生成二维码，用 B 站手机客户端扫一扫，并在手机上确认。</li></ul><p>登录凭证只保存在本机 <code>~/.luckydraw/config.json</code>。</p><h2 id="_3-添加频道" tabindex="-1">3. 添加频道 <a class="header-anchor" href="#_3-添加频道" aria-label="Permalink to &quot;3. 添加频道&quot;">​</a></h2><p>进入「设置 → 选人」，把要监控的房间号填进去；也可以直接粘贴直播间链接，例如 <code>https://live.bilibili.com/12345</code>。支持添加多个频道，所有参与者汇总到同一个抽奖池。</p><p>回到「选人」页，右侧频道列表会显示每个频道的封面、主播和在线人数，点一下切换预览。</p><h2 id="_4-开始抽奖" tabindex="-1">4. 开始抽奖 <a class="header-anchor" href="#_4-开始抽奖" aria-label="Permalink to &quot;4. 开始抽奖&quot;">​</a></h2><p>在选人页设置弹幕口令和中选人数（1–9999），然后点「开始选人」。观众发送含口令的弹幕后，参与人数会实时上涨：</p><ul><li>口令留空 = 收集全部弹幕。</li><li>弹幕区会同步显示当前频道的弹幕；向上滚动可回看，几秒后自动回到最新。</li><li>想开奖时点「停止选人」，随机抽出的中奖名单立刻展示，并自动记入历史。</li></ul><p>中奖人数较多时，名单在卡片内滚动，不影响页面整体布局。</p><h2 id="_5-查看与导出历史" tabindex="-1">5. 查看与导出历史 <a class="header-anchor" href="#_5-查看与导出历史" aria-label="Permalink to &quot;5. 查看与导出历史&quot;">​</a></h2><p>设置页的「历史」页签按当前配置列出开奖记录：</p><ul><li>点「导出」把该次名单保存为 Markdown（<code>口令-人数-时间.md</code>）。</li><li>可以单条删除，或点「全部删除」清空当前配置的历史。</li></ul><h2 id="_6-切换外观与语言" tabindex="-1">6. 切换外观与语言 <a class="header-anchor" href="#_6-切换外观与语言" aria-label="Permalink to &quot;6. 切换外观与语言&quot;">​</a></h2><p>设置页的「界面」页签可以切换深浅色、背景（默认渐变 / 春节 / 假日 / 自定义图片）和语言（中文 / English）。切换立即生效并自动记住。</p><div class="tip custom-block"><p class="custom-block-title">快捷键提示</p><p>侧栏可以在窄窗口下收起；弹幕与中奖名单的滚动条只在滚动时出现，避免干扰视线。</p></div>',22)])])}const _=t(l,[["render",o]]);export{u as __pageData,_ as default};
